begin;
select no_plan();
insert into auth.users(id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values
('b11a1000-0000-4000-8000-000000000001','authenticated','authenticated','quality-security-a@example.test','',now(),'{}','{"name":"Quality Security A","company_name":"Quality Security A"}',now(),now()),
('b11a1000-0000-4000-8000-000000000002','authenticated','authenticated','quality-security-b@example.test','',now(),'{}','{"name":"Quality Security B","company_name":"Quality Security B"}',now(),now()),
('b11a1000-0000-4000-8000-000000000003','authenticated','authenticated','quality-security-tech@example.test','',now(),'{}','{"name":"Quality Technician","company_name":"Quality Technician"}',now(),now());
update public.profiles set company_id=(select company_id from public.profiles where auth_user_id='b11a1000-0000-4000-8000-000000000001'),role='producao' where auth_user_id='b11a1000-0000-4000-8000-000000000003';
select set_config('request.jwt.claims','{"sub":"b11a1000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select set_config('qs.company',private.current_company_id(),true);
select set_config('qs.manager',(select id from public.profiles where auth_user_id=auth.uid()),true);
select set_config('qs.tech',(select id from public.profiles where auth_user_id='b11a1000-0000-4000-8000-000000000003'),true);
insert into public.customers(id,company_id,name,document) values('js-customer',private.current_company_id(),'Cliente QC QA','');
insert into public.products(id,company_id,name,pricing_type,base_cost,sales_price,stock_controlled,current_stock,min_stock) values('js-material',private.current_company_id(),'Material QC QA','unidade',2,5,true,10,0);
insert into public.orders(id,company_id,customer_id,customer_name,number,status,total_amount,paid_amount,payment_status,shipping_cost,deadline,notes) values('js-order',private.current_company_id(),'js-customer','Cliente QC QA','PED-11JS','producao',100,0,'pendente',0,now()+interval '2 days','QA');
insert into public.order_items(id,order_id,product_id,product_name,quantity,unit_price,total_price,details) values('js-item','js-order','js-material','Material QC QA',10,10,100,'{}');
insert into public.production_queue(id,company_id,order_id,order_number,order_item_id,product_name,quantity,status) values('js-queue',private.current_company_id(),'js-order','PED-11JS','js-item','Material QC QA',10,'fila');
create function pg_temp.qs_create(kind text default 'production',reference text default 'js-queue',patch jsonb default '{}') returns jsonb language sql as $$select public.quality_command(gen_random_uuid(),'create',jsonb_build_object('source_type',kind,'source_id',reference,'source_item_id',case when kind='order' then 'js-item' end,'source_updated_at',public.quality_origins(kind,'',0,reference,case when kind='order' then 'js-item' end)#>>'{origin,version}','description','Não conformidade sintética de segurança','category','print_defect','severity','medium','affected_quantity',2,'assigned_profile_id',current_setting('qs.manager'),'cost_applicable',true)||patch)$$;
create function pg_temp.qs(a text,patch jsonb default '{}') returns jsonb language sql as $$select public.quality_command(gen_random_uuid(),a,(select jsonb_build_object('id',id,'updated_at',updated_at,'cost_version',public.quality_source(current_date,current_date,id)#>>'{cases,0,cost_version}') from public.quality_nonconformities where id=current_setting('qs.id')::uuid)||patch)$$;
grant execute on function pg_temp.qs_create(text,text,jsonb),pg_temp.qs(text,jsonb) to authenticated;
set local role authenticated;
select set_config('qs.id',pg_temp.qs_create()->>'id',true);
select throws_like($$select pg_temp.qs_create('production','js-queue','{"company_id":"forged"}')$$,'%Sem permissão%','company cannot be supplied by the browser');
select throws_like($$select pg_temp.qs_create('production','js-queue','{"assigned_profile_id":"not-a-profile"}')$$,'%Responsável%','unknown assignee denied');
select throws_like($$update public.quality_nonconformities set severity='low'$$,'%permission denied%','direct case DML denied');
select throws_like($$select secret from private.quality_cost_salts$$,'%permission denied%','cost revision salt is never client-readable');
select throws_like($$select private.quality_cost_version(current_setting('qs.id')::uuid)$$,'%permission denied%','client cannot invoke financial fact fingerprint helper directly');
select throws_like($$select public.quality_commit_upload(gen_random_uuid(),auth.uid(),repeat('a',64),100)$$,'%permission denied%','trusted upload commit is not client-executable');
select lives_ok($$select pg_temp.qs('analyze','{"root_cause":"Erro de configuração identificado","analysis":"Conferência sintética"}')$$,'analysis for permission scenario');
select throws_like($$select pg_temp.qs('action_define',jsonb_build_object('kind','rework','execution_mode','internal','quantity',1,'assigned_profile_id',current_setting('qs.manager'),'notes','Escopo insuficiente para a NC'))$$,'%toda a quantidade afetada%','partial Order reproduction still covers entire affected NC scope');
select lives_ok($$select pg_temp.qs('action_define',jsonb_build_object('kind','rework','execution_mode','internal','quantity',2,'assigned_profile_id',current_setting('qs.manager'),'notes','Refazer as duas unidades afetadas'))$$,'plan a partial subset of original commercial quantity');
reset role;
insert into public.role_permissions(company_id,path,roles) values(current_setting('qs.company'),'/orders',array[]::text[]),(current_setting('qs.company'),'/production',array[]::text[]) on conflict(company_id,path) do update set roles=excluded.roles;
set local role authenticated;
select throws_like($$select public.quality_origins('order')$$,'%Sem permissão%','explicit Order deny wins over admin fallback');
select throws_like($$select public.quality_origins('production')$$,'%Sem permissão%','explicit Production deny wins over admin fallback');
select throws_like($$select pg_temp.qs_create('order','js-order')$$,'%Sem permissão%','direct create cannot bypass denied Order context');
select throws_like($$select pg_temp.qs('action_start',jsonb_build_object('production_updated_at',(select updated_at from public.production_queue where id='js-queue')))$$,'%Sem permissão%','direct execution cannot bypass denied Production');
select is((select execution_number from public.production_queue where id='js-queue'),1,'denied start never changes execution metadata');
reset role;
delete from public.role_permissions where company_id=current_setting('qs.company') and path in('/orders','/production');
set local role authenticated;
select set_config('qs.operation',gen_random_uuid()::text,true);
select set_config('qs.cost_payload',(select jsonb_build_object('id',id,'updated_at',updated_at,'kind','labor','description','Despesa adicional QA','planned',10,'actual',8)::text from public.quality_nonconformities where id=current_setting('qs.id')::uuid),true);
select lives_ok($$select public.quality_command(current_setting('qs.operation')::uuid,'cost_save',current_setting('qs.cost_payload')::jsonb)$$,'finance records actual without moving cash');
select is((select count(*) from public.financial_transactions where company_id=current_setting('qs.company')),0::bigint,'cost fact never creates cash or a payable automatically');
reset role;
insert into public.role_permissions(company_id,path,roles) values(current_setting('qs.company'),'/financial',array[]::text[]) on conflict(company_id,path) do update set roles=excluded.roles;
set local role authenticated;
select throws_like($$select public.quality_command(current_setting('qs.operation')::uuid,'cost_save',current_setting('qs.cost_payload')::jsonb)$$,'%Sem permissão%','receipt replay revalidates financial permission');
select is(public.quality_source(current_date,current_date,current_setting('qs.id')::uuid)->'costs','[]'::jsonb,'explicit financial deny masks costs even for admin');
reset role;
delete from public.role_permissions where company_id=current_setting('qs.company') and path='/financial';
select set_config('request.jwt.claims','{"sub":"b11a1000-0000-4000-8000-000000000003","role":"authenticated"}',true);
set local role authenticated;
select is(public.quality_source(current_date,current_date,current_setting('qs.id')::uuid)->'summaries','{}'::jsonb,'technician sees no financial summaries');
select is(public.quality_source(current_date,current_date,current_setting('qs.id')::uuid)->'cost_history','[]'::jsonb,'financial history remains protected');
select throws_like($$select unit_cost from public.quality_materials$$,'%permission denied%','material unit cost cannot be selected directly');
select throws_like($$select pg_temp.qs('action_start',jsonb_build_object('production_updated_at',(select updated_at from public.production_queue where id='js-queue')))$$,'%Sem permissão%','unassigned operator cannot execute case');
reset role;
select set_config('request.jwt.claims','{"sub":"b11a1000-0000-4000-8000-000000000002","role":"authenticated"}',true);
set local role authenticated;
select is((select count(*) from public.quality_nonconformities),0::bigint,'tenant B sees no A cases');
select is(jsonb_array_length(public.quality_links('order',array['js-order'])->'links'),0,'tenant B cannot enumerate A references');
select throws_like($$select public.quality_source(current_date,current_date,current_setting('qs.id')::uuid)$$,'%indisponível%','foreign detail denied');
select throws_like($$select public.quality_command(gen_random_uuid(),'update',jsonb_build_object('id',current_setting('qs.id'),'updated_at',now(),'description','Alteração de outro tenant'))$$,'%indisponível%','foreign mutation denied');
reset role;
select * from finish();rollback;
